package helper

import (
	"fmt"
	"strings"

	"github.com/iancoleman/strcase"
	"github.com/tableauio/tableau/proto/tableaupb"
	"google.golang.org/protobuf/compiler/protogen"
	"google.golang.org/protobuf/proto"
	"google.golang.org/protobuf/reflect/protoreflect"
	"google.golang.org/protobuf/types/descriptorpb"
)

// GenerateFileHeader writes the auto-generated file header comment block,
// including version info and source path. If file is non-nil, the source path
// (or deprecation notice) is included.
func GenerateFileHeader(gen *protogen.Plugin, file *protogen.File, g *protogen.GeneratedFile, version string) {
	g.P("// @generated by protoc-gen-ts-tableau-loader. DO NOT EDIT.")
	g.P("// versions:")
	g.P("// - protoc-gen-ts-tableau-loader v", version)
	g.P("// - protoc                ", protocVersion(gen))
	if file != nil {
		if file.Proto.GetOptions().GetDeprecated() {
			g.P("// ", file.Desc.Path(), " is a deprecated file.")
		} else {
			g.P("// source: ", file.Desc.Path())
		}
	}
	g.P("/* eslint-disable */")
	g.P()
}

// protocVersion returns the protoc compiler version string (e.g. "v3.19.3").
func protocVersion(gen *protogen.Plugin) string {
	v := gen.Request.GetCompilerVersion()
	if v == nil {
		return "(unknown)"
	}
	var suffix string
	if s := v.GetSuffix(); s != "" {
		suffix = "-" + s
	}
	return fmt.Sprintf("v%d.%d.%d%s", v.GetMajor(), v.GetMinor(), v.GetPatch(), suffix)
}

// MessagerName returns the TypeScript class name for a worksheet message.
// Worksheet messages are always top-level, so this is just the short name.
func MessagerName(md protoreflect.MessageDescriptor) string {
	return string(md.Name())
}

// LocalTypeName returns the protobuf-es local type name for a message or enum,
// which joins the nested type path with underscores after stripping the package
// (e.g. "protoconf.ThemeConf.Theme" -> "ThemeConf_Theme",
// "protoconf.UseEffect.Type" -> "UseEffect_Type"). Works for top-level and
// nested descriptors alike.
func LocalTypeName(d protoreflect.Descriptor) string {
	full := string(d.FullName())
	if pkg := string(d.ParentFile().Package()); pkg != "" {
		full = strings.TrimPrefix(full, pkg+".")
	}
	return strings.ReplaceAll(full, ".", "_")
}

// LocalSchemaName returns the protobuf-es schema export name for any message,
// top-level or nested (e.g. "protoconf.ThemeConf.Theme" -> "ThemeConf_ThemeSchema").
func LocalSchemaName(d protoreflect.Descriptor) string {
	return LocalTypeName(d) + "Schema"
}

// PackageAlias converts a protobuf package name into a valid TypeScript
// namespace-import alias by replacing dots with underscores (e.g. "foo.bar" ->
// "foo_bar"). This alias is used as the namespace for a package's barrel import
// (import * as <alias>), so generated loaders qualify types exactly like the
// loaders of other languages do (e.g. protoconf.ItemConf, base.Hero), keeping
// cross-language naming consistent. Empty packages fall back to "pb".
func PackageAlias(pkg string) string {
	if pkg == "" {
		return "pb"
	}
	return strings.ReplaceAll(pkg, ".", "_")
}

// ScalarTSType returns the plain TypeScript type for a protobuf scalar kind.
// ok is false for non-scalar kinds (message/group/enum), letting callers handle
// those via alias-qualified named types instead.
func ScalarTSType(kind protoreflect.Kind) (string, bool) {
	switch kind {
	case protoreflect.BoolKind:
		return "boolean", true
	case protoreflect.StringKind:
		return "string", true
	case protoreflect.BytesKind:
		return "Uint8Array", true
	case protoreflect.Int32Kind, protoreflect.Sint32Kind, protoreflect.Sfixed32Kind,
		protoreflect.Uint32Kind, protoreflect.Fixed32Kind,
		protoreflect.FloatKind, protoreflect.DoubleKind:
		return "number", true
	case protoreflect.Int64Kind, protoreflect.Sint64Kind, protoreflect.Sfixed64Kind,
		protoreflect.Uint64Kind, protoreflect.Fixed64Kind:
		return "bigint", true
	default:
		return "", false
	}
}

// MapKey represents a single key component of a (possibly nested) map getter.
type MapKey struct {
	// ParamType is the TypeScript getter parameter type (number/bigint/string/boolean).
	ParamType string
	// IdxKind is the TypeScript index-signature kind of the protobuf-es map
	// object (number or string), used to build indexed-access return types.
	IdxKind string
	// Name is the getter parameter name (deduplicated across nested levels).
	Name string
	// NeedToString reports whether the parameter must be stringified to index
	// the underlying map object (true for 64-bit / bool keys).
	NeedToString bool
}

// IndexExpr returns the expression used to index the underlying map object.
func (k MapKey) IndexExpr() string {
	if k.NeedToString {
		return k.Name + ".toString()"
	}
	return k.Name
}

// MapKeySlice is an ordered collection of MapKey entries.
type MapKeySlice []MapKey

// AddMapKey appends a new map key, deduplicating the parameter Name across
// nested levels (e.g. "id" -> "id3") so generated getter signatures are valid.
func (s MapKeySlice) AddMapKey(newKey MapKey) MapKeySlice {
	if newKey.Name == "" {
		newKey.Name = fmt.Sprintf("key%d", len(s)+1)
	}
	for _, key := range s {
		if key.Name == newKey.Name {
			newKey.Name = fmt.Sprintf("%s%d", newKey.Name, len(s)+1)
			break
		}
	}
	return append(s, newKey)
}

// GenGetParams generates the getter parameter list (e.g. "id: number, name: string").
func (s MapKeySlice) GenGetParams() string {
	var params []string
	for _, key := range s {
		params = append(params, key.Name+": "+key.ParamType)
	}
	return strings.Join(params, ", ")
}

// GenGetArguments generates the getter argument list (e.g. "id, name").
func (s MapKeySlice) GenGetArguments() string {
	var args []string
	for _, key := range s {
		args = append(args, key.Name)
	}
	return strings.Join(args, ", ")
}

// ParseMapKey returns the MapKey metadata (param type, index kind, stringify
// flag) for a map field's key descriptor (fd must be a map key descriptor).
func ParseMapKey(keyFd protoreflect.FieldDescriptor, name string) MapKey {
	key := MapKey{Name: name}
	switch keyFd.Kind() {
	case protoreflect.Int32Kind, protoreflect.Sint32Kind, protoreflect.Sfixed32Kind,
		protoreflect.Uint32Kind, protoreflect.Fixed32Kind:
		key.ParamType = "number"
		key.IdxKind = "number"
		key.NeedToString = false
	case protoreflect.Int64Kind, protoreflect.Sint64Kind, protoreflect.Sfixed64Kind,
		protoreflect.Uint64Kind, protoreflect.Fixed64Kind:
		key.ParamType = "bigint"
		key.IdxKind = "string"
		key.NeedToString = true
	case protoreflect.BoolKind:
		key.ParamType = "boolean"
		key.IdxKind = "string"
		key.NeedToString = true
	case protoreflect.StringKind:
		key.ParamType = "string"
		key.IdxKind = "string"
		key.NeedToString = false
	default:
		// Map keys can only be integral, bool, or string.
		key.ParamType = "string"
		key.IdxKind = "string"
		key.NeedToString = false
	}
	return key
}

// ParseMapFieldNameAsFuncParam returns a safe lowerCamelCase getter parameter
// name for a map field key. If the map value is a message type, the first field
// name of the value message is used; otherwise the tableau field option "key"
// is used.
func ParseMapFieldNameAsFuncParam(fd protoreflect.FieldDescriptor) string {
	opts := fd.Options().(*descriptorpb.FieldOptions)
	fdOpts := proto.GetExtension(opts, tableaupb.E_Field).(*tableaupb.FieldOptions)
	name := fdOpts.GetKey()
	if fd.MapValue().Kind() == protoreflect.MessageKind {
		valueFd := fd.MapValue().Message().Fields().Get(0)
		name = string(valueFd.Name())
	}
	if name == "" {
		return ""
	}
	return escapeIdentifier(strcase.ToLowerCamel(name))
}

// FieldLocalName returns the protobuf-es local (JS property) name for a field,
// which is the lowerCamelCase form of the protobuf field name.
func FieldLocalName(fd protoreflect.FieldDescriptor) string {
	return strcase.ToLowerCamel(string(fd.Name()))
}

// tsReservedWords are TypeScript/JavaScript reserved words that cannot be used
// as bare identifiers for function parameters.
var tsReservedWords = map[string]bool{
	"break": true, "case": true, "catch": true, "class": true, "const": true,
	"continue": true, "debugger": true, "default": true, "delete": true, "do": true,
	"else": true, "enum": true, "export": true, "extends": true, "false": true,
	"finally": true, "for": true, "function": true, "if": true, "import": true,
	"in": true, "instanceof": true, "new": true, "null": true, "return": true,
	"super": true, "switch": true, "this": true, "throw": true, "true": true,
	"try": true, "typeof": true, "var": true, "void": true, "while": true,
	"with": true, "let": true, "static": true, "yield": true, "await": true,
}

// escapeIdentifier escapes a TypeScript reserved word by appending an
// underscore, producing a valid identifier.
func escapeIdentifier(name string) string {
	if tsReservedWords[name] {
		return name + "_"
	}
	return name
}

// Indent returns a string of 2*depth spaces, used for indenting generated
// TypeScript code blocks at the specified nesting depth.
func Indent(depth int) string {
	return strings.Repeat("  ", depth)
}
